// Il corpo GREZZO, byte per byte, e la firma che lo accompagna.
//
// Qui non si decide niente: tutta la logica del ponte vive nella funzione
// Postgres `calcom_webhook()` (migration 0037). Questo nodo esiste per una
// ragione sola, ed è la ragione per cui questi ponti falliscono: la firma di
// Cal.com è un HMAC-SHA256 sui byte esatti che sono arrivati. Un JSON parsato e
// riserializzato da n8n dà una firma diversa anche a contenuto identico —
// l'ordine delle chiavi, gli spazi e il formato dei numeri non sopravvivono al
// giro. Per questo il nodo Webhook ha "Raw Body" acceso e qui si decodifica.
//
// Se il corpo grezzo non arriva, questo nodo FALLISCE di proposito, invece di
// ripiegare su una riserializzazione: un ponte configurato male deve essere
// rumoroso. Il ripiego silenzioso produrrebbe "firma_non_valida" su ogni
// messaggio, che è il modo peggiore di rompersi — sembra un problema di segreti
// e non lo è.
const item = $input.first();

const b64 = item.binary && item.binary.data && item.binary.data.data;
if (!b64) {
  throw new Error(
    'Il nodo Webhook non ha consegnato il corpo grezzo. Controlla che l\'opzione ' +
    '"Raw Body" sia accesa: senza i byte originali la firma non si può verificare.'
  );
}

const corpo = Buffer.from(b64, 'base64').toString('utf8');
const headers = item.json.headers || {};
const firma = headers['x-cal-signature-256'] || '';

return [{ json: { corpo, firma } }];
